import { Component } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { AuthClientesService } from '../auth.service';
import { Router } from '@angular/router';

@Component({
    selector: 'app-login-clientes',
    imports: [
        FormsModule,
    ],
    templateUrl: './login-clientes.component.html',
    styleUrl: './login-clientes.component.css'
})
export class LoginClientesComponent {
  email=''
  password=''

  constructor(
    private auth: AuthClientesService,
    private router:Router,
  ){}

  public async submit(){
    const user = await this.auth.login(this.email, this.password)
    if(user){
      this.router.navigate(['/clientes/main'])
    }
  }
}
